/bin/bash -lc "python3 - <<'PY'
from collections import defaultdict
# parse mapping from fasta gz? use local mapping built from gencode fasta headers quickly
import gzip
sym={}
with gzip.open('/workspace/refs/gencode.v47.transcripts.fa.gz','rt') as f:
    for line in f:
        if line.startswith('>'):
            p=line[1:].strip().split('|'); sym[p[0]]=p[5]
def readq(path):
    d={}
    with open(path) as f:
        next(f)
        for line in f:
            p=line.rstrip('\\n').split('\\t')
            d[p[0]]=float(p[4])
    return d
A=readq('/workspace/salmon_A_sorted.tsv'); B=readq('/workspace/salmon_B_sorted.tsv')
genes=defaultdict(lambda: {'a':0.0,'b':0.0,'tx':[]})
for tx in set(A)|set(B):
    g=sym.get(tx); 
    if not g: continue
    a=A.get(tx,0); b=B.get(tx,0)
    genes[g]['a']+=a; genes[g]['b']+=b
    if a>0 or b>0: genes[g]['tx'].append((tx,a,b))
rows=[]
for g,d in genes.items():
    if len(d['tx'])<2: continue
    ta=d['a']; tb=d['b']
    if min(ta,tb)==0: continue
    score=0.5*sum(abs((x[1]/ta if ta else 0)-(x[2]/tb if tb else 0)) for x in d['tx'])
    maxd=max(abs((x[1]/ta if ta else 0)-(x[2]/tb if tb else 0)) for x in d['tx'])
    rows.append((g,ta,tb,score,maxd,len(d['tx']),d['tx']))
for minreads in [10,20,50,100,200]:
    sub=[r for r in rows if min(r[1],r[2])>=minreads]
    sub.sort(key=lambda r:(-r[3],-min(r[1],r[2])))
    print('MIN READS',minreads,'count',len(sub))
    for r in sub[:10]:
        print(' ',r[0],'readsA',round(r[1],1),'readsB',round(r[2],1),'score',round(r[3],3),'max',round(r[4],3),'n',r[5])
PY"

